  let lang = valid(requested) ? requested : valid(saved) ? saved : 'ko';
  try { localStorage.setItem('cic-language',lang); } catch {}
  const pattern = new RegExp(Object.keys(messages).sort((a,b)=>b.length-a.length).map(s=>s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g');
  const t = source => lang === 'ko' ? String(source) : String(source).replace(pattern, match => messages[match]);
  // Translate literal template parts before inserting values; user data stays untouched.
  const html = (parts,...values) => parts.reduce((out,part,i)=>out+t(part)+(i<values.length?values[i]:''),'');
  function setLanguage(next) {
    if (!valid(next) || next === lang) return false;
    lang = next;
    try { localStorage.setItem('cic-language',lang); } catch {}
    try { const url = new URL(location.href); url.searchParams.set('lang',lang); history.replaceState(null,'',url); } catch {}
    return true;
  }
